def f(I):
    H,W=len(I),len(I[0]); out=[]
    for i in range(H//3):
        row=[]
        for j in range(W//3):
            colors={I[r][c] for r in range(3*i,3*i+3) for c in range(3*j,3*j+3)}-{0,5}
            # most frequent non-5 non-0
            cnt={}
            for r in range(3*i,3*i+3):
                for c in range(3*j,3*j+3):
                    v=I[r][c]
                    if v not in(0,5): cnt[v]=cnt.get(v,0)+1
            mv=max(cnt.items(), key=lambda kv:kv[1])[0] if cnt else 0
            row.append(mv)
        out.append(row)
    return out

